function CommonPreviewListPopup:RefreshLoopListView(maxNum)
    if not self.LoopListView.IsListViewInit then
        self.LoopListView:InitListView(maxNum, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopListView, maxNum)
    end
end

function CommonPreviewListPopup:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end

    local luaIndex = index + 1
    local cellType = self:GetNodeType(luaIndex)
    local cell = loopListView:NewListViewItem(self:GetCellName(cellType))
    local LB_cell = GetLuaBehaviour(cell.gameObject, self:GetLuaPath(cellType))
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        LB_cell:Init()
    end
    local LT_cell = LB_cell.Env
    LT_cell:SetData(self.data, luaIndex)
    if isNotNull(LT_cell.SetGetOneCallback) then
        LT_cell:SetGetOneCallback(Bind(self, self.Refresh))
    end
    LT_cell:Refresh()

    return cell
end

function CommonPreviewListPopup:GetNodeType(luaIndex)
    local list = checkTable(self.data.nodeDataList)
    if isNull(list[luaIndex]) then
        return 1
    end
    local data = list[luaIndex]
    if isNull(data.type) then
        return 1
    end
    return checkNumber(data.type)
end

function CommonPreviewListPopup:GetCellName(cellType)
    if cellType == 1 then
        return "Cell"
    else
        return "Cell"..cellType
    end
end

function CommonPreviewListPopup:GetLuaPath(cellType)
    if type(self.data.nodeLuaPath) ~= "table" then
        return self.data.nodeLuaPath
    else
        return self.data.nodeLuaPath[cellType]
    end
end

return CommonPreviewListPopup
